INSERT INTO sources VALUES ('S1','A Reference Grammar of Chinese — Classifiers (Cambridge University Press)','https://www.cambridge.org/core/books/abs/reference-grammar-of-chinese/classifiers/8612AD1692A82231F47229F4A20E80C2','Общая грамматика: структура числительное/указательное слово + классификатор + существительное; различие классификаторов и мерных слов.');
INSERT INTO sources VALUES ('S2','Measure Words (Classifiers) in Chinese — Settemila Lingue','https://www.settemilalingue.com/en/languages/zh/grammar/measure-words-classifiers','Базовые пары: 个, 本, 张, 杯, 只; пояснение, что 个 — широкий, но не универсальный заменитель.');
INSERT INTO sources VALUES ('S3','115 Frequently Used Chinese Measure Words — DigMandarin','https://www.digmandarin.com/chinese-measure-words','Список частотных классификаторов по категориям и примеры типичных сочетаний.');
INSERT INTO sources VALUES ('S4','Chinese Measure Words / Classifiers — Polyglot101','https://www.polyglot101.com/en/languages/chinese/grammar/classifiers/','Категории 张, 本, 件, 条, 块, 支, 双, 杯 и примеры.');
INSERT INTO sources VALUES ('S5','On the Idiosyncrasies of the Mandarin Chinese Classifier System','https://arxiv.org/abs/1902.10193','Исследовательский контекст: выбор классификаторов частично определяется семантическим классом, особенно формой предмета, но остаётся идиоматичным.');
INSERT INTO classifiers VALUES ('CL001','个','gè','общий','Широкий общий классификатор; в игре — базовое оружие.',1,'Использовать как игровой fallback, но не считать универсально правильным.','S2;S3');
INSERT INTO classifiers VALUES ('CL002','位','wèi','люди','Вежливый классификатор людей: учителя, гости, специалисты.',2,'Подчёркивает уважение/вежливость.','S3');
INSERT INTO classifiers VALUES ('CL003','名','míng','люди','Формальный классификатор людей, профессий и участников.',2,'Часто в официальной речи, статистике, новостях.','S3');
INSERT INTO classifiers VALUES ('CL004','只','zhī','животные/парные части','Многие животные; также один предмет из естественной пары.',1,'Один из самых полезных ранних классификаторов.','S2;S3');
INSERT INTO classifiers VALUES ('CL005','头','tóu','крупные животные','Скот и некоторые крупные животные.',3,'Часто для коров, свиней, овец, слонов.','S3');
INSERT INTO classifiers VALUES ('CL006','匹','pǐ','животные','Лошади и некоторые ездовые животные.',3,'Очень специфичный и удобный для запоминания.','S3');
INSERT INTO classifiers VALUES ('CL007','条','tiáo','длинное/гибкое','Длинные, узкие или извилистые объекты; рыбы, змеи, дороги, реки, одежда.',1,'Смысловой класс широкий, но устойчивый.','S3;S4');
INSERT INTO classifiers VALUES ('CL008','棵','kē','растения','Деревья и отдельные растения с корнем/стволом.',2,'Не путать с 颗 kē для маленьких округлых объектов.','S3');
INSERT INTO classifiers VALUES ('CL009','朵','duǒ','цветы/облака','Цветы, облака и похожие по форме объекты.',2,'Хорошо визуализируется.','S3');
INSERT INTO classifiers VALUES ('CL010','本','běn','книги','Переплетённые издания: книги, журналы, словари, тетради.',1,'Каноническая ранняя пара 一本书.','S2;S3;S4');
INSERT INTO classifiers VALUES ('CL011','张','zhāng','плоское/расправленное','Плоские предметы и поверхности: бумага, билеты, фотографии, столы, кровати.',1,'Выбор частично идиоматичен.','S2;S3;S4');
INSERT INTO classifiers VALUES ('CL012','支','zhī','длинное/прямое','Прямые палочкообразные предметы: ручки, карандаши, кисти.',1,'Иероглиф совпадает по чтению с 只, но это другое слово.','S3;S4');
INSERT INTO classifiers VALUES ('CL013','根','gēn','тонкое/длинное','Тонкие длинные объекты и нити: волосы, верёвки, палки.',2,'Часто обозначает одну отдельную нить/стержень.','S3');
INSERT INTO classifiers VALUES ('CL014','把','bǎ','предметы с ручкой','Предметы, которые держат рукой: ножи, зонты, веера, стулья.',2,'Также может означать горсть/связку в мерном значении.','S3');
INSERT INTO classifiers VALUES ('CL015','件','jiàn','одежда/дела','Предметы одежды, дела, события, подарки и отдельные предметы.',1,'Очень частотный и семантически широкий.','S3;S4');
INSERT INTO classifiers VALUES ('CL016','顶','dǐng','головные уборы','Шляпы, шапки и другие головные уборы.',3,'Специфический классификатор.','S3');
INSERT INTO classifiers VALUES ('CL017','双','shuāng','пары','Пары одинаковых предметов: обувь, носки, перчатки, палочки.',1,'Важно отличать единичный предмет от пары.','S3;S4');
INSERT INTO classifiers VALUES ('CL018','辆','liàng','транспорт','Колёсный дорожный транспорт.',1,'Автомобили, автобусы, велосипеды, мотоциклы.','S3');
INSERT INTO classifiers VALUES ('CL019','架','jià','техника/авиация','Самолёты, вертолёты и некоторые машины/аппараты.',2,'Для авиации — канонический выбор.','S3');
INSERT INTO classifiers VALUES ('CL020','艘','sōu','водный транспорт','Корабли, лодки, суда.',3,'Специфический классификатор судов.','S3');
INSERT INTO classifiers VALUES ('CL021','列','liè','транспорт/ряды','Поезда и вытянутые последовательности.',3,'Канонически для поездов.','S3');
INSERT INTO classifiers VALUES ('CL022','台','tái','техника','Машины и бытовая/электронная техника.',1,'Компьютеры, телевизоры, холодильники и т. п.','S3');
INSERT INTO classifiers VALUES ('CL023','部','bù','медиа/устройства','Фильмы, крупные произведения, телефоны и некоторые устройства.',2,'Смысл зависит от существительного.','S3');
INSERT INTO classifiers VALUES ('CL024','间','jiān','помещения','Комнаты и отдельные помещения.',1,'Канонический классификатор комнаты.','S3');
INSERT INTO classifiers VALUES ('CL025','栋','dòng','здания','Отдельные многоэтажные или крупные здания.',3,'Хорошо подходит для визуальных врагов-зданий.','S3');
INSERT INTO classifiers VALUES ('CL026','所','suǒ','учреждения','Школы, больницы, университеты и учреждения.',2,'Считает учреждение как организацию/комплекс.','S3');
INSERT INTO classifiers VALUES ('CL027','座','zuò','крупные сооружения','Мосты, горы, башни, храмы и крупные неподвижные объекты.',2,'Широкий, но образный класс.','S3');
INSERT INTO classifiers VALUES ('CL028','扇','shàn','створки','Двери, окна и объекты на петлях.',3,'Визуально понятная категория.','S3');
INSERT INTO classifiers VALUES ('CL029','堵','dǔ','стены','Стены и преграды.',3,'Часто 一堵墙.','S3');
INSERT INTO classifiers VALUES ('CL030','封','fēng','письма','Письма и корреспонденция в конверте.',2,'Каноническая пара 一封信.','S3');
INSERT INTO classifiers VALUES ('CL031','篇','piān','тексты','Статьи, сочинения и законченные письменные тексты.',2,'Канонически для 文章.','S3');
INSERT INTO classifiers VALUES ('CL032','首','shǒu','стихи/песни','Стихотворения и песни.',2,'Один классификатор на два близких культурных объекта.','S3');
INSERT INTO classifiers VALUES ('CL033','句','jù','фразы','Предложения, реплики, отдельные высказывания.',1,'Очень полезный ранний классификатор.','S3');
INSERT INTO classifiers VALUES ('CL034','则','zé','сообщения','Новости, объявления, реклама, короткие истории.',3,'Более книжный/официальный регистр.','S3');
INSERT INTO classifiers VALUES ('CL035','幅','fú','изображения','Картины, рисунки, каллиграфические работы.',2,'Для фотографии чаще 张; для картины 幅.','S3');
INSERT INTO classifiers VALUES ('CL036','通','tōng','звонки','Телефонные звонки и некоторые протяжённые действия связи.',3,'Канонически 一通电话.','S3');
INSERT INTO classifiers VALUES ('CL037','杯','bēi','ёмкость','Чашка/стакан напитка.',1,'Это мерное слово: считает порцию жидкости.','S2;S3;S4');
INSERT INTO classifiers VALUES ('CL038','瓶','píng','ёмкость','Бутылка напитка или вещества.',1,'Мерное слово, меняющее значение количества.','S3');
INSERT INTO classifiers VALUES ('CL039','碗','wǎn','ёмкость','Миска/пиала еды или напитка.',1,'Мерное слово.','S3');
INSERT INTO classifiers VALUES ('CL040','道','dào','блюда/задания','Отдельное блюдо; также задача или вопрос.',2,'Два устойчивых значения.','S3');
INSERT INTO classifiers VALUES ('CL041','顿','dùn','приёмы пищи','Приёмы пищи.',2,'Завтрак, обед, ужин как событие.','S3');
INSERT INTO classifiers VALUES ('CL042','块','kuài','кусок/фрагмент','Куски, ломтики, глыбы, части плотного материала.',1,'Также разговорная денежная единица.','S3;S4');
INSERT INTO classifiers VALUES ('CL043','片','piàn','тонкий фрагмент','Тонкие ломтики, листья, пласты.',2,'Подчёркивает плоский тонкий фрагмент.','S3');
INSERT INTO classifiers VALUES ('CL044','颗','kē','малое округлое','Небольшие округлые предметы: жемчужины, звёзды, семена, зубы.',2,'Не путать с 棵 kē.','S3');
INSERT INTO classifiers VALUES ('CL045','粒','lì','очень мелкое','Зёрна, таблетки, мелкие частицы.',2,'Подчёркивает малый размер.','S3');
INSERT INTO classifiers VALUES ('CL046','场','chǎng','события/явления','Крупные события, спектакли, игры, дождь/снег как эпизод.',2,'Контекстно широкий классификатор.','S3');
INSERT INTO classifiers VALUES ('CL047','阵','zhèn','краткие явления','Краткие порывы, ливни, всплески звука или эмоций.',3,'Подчёркивает внезапность и краткость.','S3');
INSERT INTO classifiers VALUES ('CL048','次','cì','повторения','Количество раз/случаев действия.',1,'Считает событие, а не предмет.','S3');
INSERT INTO classifiers VALUES ('CL049','节','jié','занятия/секции','Уроки и части последовательности.',1,'Канонически 一节课.','S3');
INSERT INTO classifiers VALUES ('CL050','门','mén','учебные предметы','Учебные дисциплины и курсы как предметы.',3,'Не путать с 门 ''дверь''.','S3');
INSERT INTO classifiers VALUES ('CL051','面','miàn','поверхности','Стены, зеркала, флаги и поверхности, воспринимаемые как одна сторона.',3,'В текущем наборе используется как естественный вариант для стены.','S3');
