-- SQLite seed database for the Chinese classifier learning game
-- Generated with separate linguistic_fit and game_damage metrics.

BEGIN TRANSACTION;

PRAGMA foreign_keys = ON;

CREATE TABLE sources (
    source_id TEXT PRIMARY KEY,
    title TEXT NOT NULL,
    url TEXT NOT NULL,
    usage_note TEXT
);

CREATE TABLE classifiers (
    classifier_id TEXT PRIMARY KEY,
    hanzi TEXT NOT NULL,
    pinyin TEXT NOT NULL,
    category TEXT NOT NULL,
    core_usage_ru TEXT NOT NULL,
    unlock_level INTEGER NOT NULL CHECK (unlock_level BETWEEN 1 AND 3),
    note TEXT,
    source_ids TEXT
);

CREATE TABLE nouns (
    noun_id TEXT PRIMARY KEY,
    noun_ru TEXT NOT NULL,
    noun_zh TEXT NOT NULL,
    noun_pinyin TEXT NOT NULL,
    category TEXT NOT NULL,
    icon_key TEXT NOT NULL,
    difficulty INTEGER NOT NULL CHECK (difficulty BETWEEN 1 AND 3),
    gameplay_eligible INTEGER NOT NULL CHECK (gameplay_eligible IN (0, 1)),
    ge_naturalness INTEGER NOT NULL CHECK (ge_naturalness BETWEEN 1 AND 5),
    note TEXT
);

CREATE TABLE noun_classifier_pairs (
    pair_id TEXT PRIMARY KEY,
    noun_id TEXT NOT NULL REFERENCES nouns(noun_id) ON DELETE CASCADE,
    classifier_id TEXT NOT NULL REFERENCES classifiers(classifier_id) ON DELETE CASCADE,
    linguistic_fit INTEGER NOT NULL CHECK (linguistic_fit BETWEEN 1 AND 5),
    game_damage INTEGER NOT NULL CHECK (game_damage BETWEEN 1 AND 5),
    relation_type TEXT NOT NULL,
    example TEXT,
    note TEXT,
    source_ids TEXT,
    UNIQUE (noun_id, classifier_id, relation_type, example)
);

CREATE INDEX idx_pairs_noun ON noun_classifier_pairs(noun_id);
CREATE INDEX idx_pairs_classifier ON noun_classifier_pairs(classifier_id);
CREATE INDEX idx_pairs_fit ON noun_classifier_pairs(linguistic_fit);
CREATE INDEX idx_nouns_gameplay ON nouns(gameplay_eligible, difficulty);

COMMIT;
